// ============================================================================
// MIPS VM Class
// ============================================================================
class MIPSVM {
  constructor(elfPath) {
    this.elfPath = elfPath;
    this.binary = fs.readFileSync(elfPath);

    // Memory: 256MB
    this.memory = Buffer.alloc(256 * 1024 * 1024);

    // Registers
    this.registers = new Int32Array(32);
    this.hi = 0;
    this.lo = 0;

    // Program counter
    this.pc = 0;

    // Execution state
    this.running = true;
    this.halt = false;
    this.cycleCount = 0;
    this.maxCycles = 100000000; // 100 million cycles max

    // File descriptor table
    this.fd_table = new Map();
    this.next_fd = 3; // 0=stdin, 1=stdout, 2=stderr
    this.open_files = new Map();

    // Virtual filesystem for output
    this.vfs = new Map();

    // ELF sections
    this.sections = new Map();
    this.symbols = new Map();

    // Breakpoints
    this.breakpoints = new Set();

    this.parseELF();
  }

  parseELF() {
    const buf = this.binary;

    // Check ELF magic
    if (buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
      throw new Error('Invalid ELF file');
    }

    // Parse ELF header
    const e_machine = buf.readUInt16LE(18);
    if (e_machine !== 0x0008) {
      throw new Error(`Not a MIPS ELF (machine type: ${e_machine})`);
    }

    const e_entry = buf.readUInt32LE(28);
    const e_phoff = buf.readUInt32LE(32);
    const e_shoff = buf.readUInt32LE(32);
    const e_phentsize = buf.readUInt16LE(42);
    const e_phnum = buf.readUInt16LE(44);
    const e_shentsize = buf.readUInt16LE(46);
    const e_shnum = buf.readUInt16LE(48);
    const e_shstrndx = buf.readUInt16LE(50);

    this.pc = e_entry;

    // Load program headers (LOAD segments)
    for (let i = 0; i < e_phnum; i++) {
      const phoff = e_phoff + i * e_phentsize;
      const p_type = buf.readUInt32LE(phoff);
      const p_offset = buf.readUInt32LE(phoff + 4);
      const p_vaddr = buf.readUInt32LE(phoff + 8);
      const p_filesz = buf.readUInt32LE(phoff + 16);
      const p_memsz = buf.readUInt32LE(phoff + 20);

      // PT_LOAD = 1
      if (p_type === 1) {
        if (p_filesz > 0) {
          buf.copy(this.memory, p_vaddr, p_offset, p_offset + p_filesz);
        }
        // Zero out BSS
        if (p_memsz > p_filesz) {
          this.memory.fill(0, p_vaddr + p_filesz, p_vaddr + p_memsz);
        }
      }
